describe('Change Email Address with Confirmation', () => {
  beforeEach(() => {
    cy.visit('/user/profile');
  });

  it('should successfully change email address after confirmation', () => {
    // Verify initial email is displayed
    cy.get('[data-testid="current-email"]').should('contain', 'user@example.com');

    // Click on change email button
    cy.get('[data-testid="change-email-btn"]').click();

    // Verify email change form appears
    cy.get('[data-testid="email-change-form"]').should('be.visible');
    cy.get('[data-testid="new-email-input"]').should('be.visible');

    // Enter new email
    cy.get('[data-testid="new-email-input"]').type('new.user@example.com');

    // Click submit button
    cy.get('[data-testid="submit-email-change"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-email-text"]').should('contain', 'new.user@example.com');

    // Click confirm button
    cy.get('[data-testid="confirm-email-btn"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Email address updated');

    // Verify email is updated in profile
    cy.get('[data-testid="current-email"]').should('contain', 'new.user@example.com');

    // Verify confirmation email was sent
    cy.get('[data-testid="confirmation-sent-status"]').should('contain', 'Email sent');
  });

  it('should prevent email change with invalid email format', () => {
    // Verify initial email is displayed
    cy.get('[data-testid="current-email"]').should('contain', 'user@example.com');

    // Click on change email button
    cy.get('[data-testid="change-email-btn"]').click();

    // Enter invalid email
    cy.get('[data-testid="new-email-input"]').type('invalid-email-format');

    // Click submit button
    cy.get('[data-testid="submit-email-change"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a valid email address');

    // Verify confirmation modal does not appear
    cy.get('[data-testid="confirmation-modal"]').should('not.exist');

    // Verify email was not changed
    cy.get('[data-testid="current-email"]').should('contain', 'user@example.com');

    // Verify error icon is displayed
    cy.get('[data-testid="error-icon"]').should('be.visible');
  });
});
